// lib/ui/screens/about_screen.dart
//
// Every metric shown here is loaded at runtime from
// assets/config/eval_results.json, which is generated by
// mobile_application/05_export/step2_eval.py from the 418 locked test images.
// NEVER hard-code accuracy, recall, or Wilson-CI values in this file.
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../core/constants.dart';

class AboutScreen extends StatefulWidget {
  const AboutScreen({super.key});

  @override
  State<AboutScreen> createState() => _AboutScreenState();
}

class _AboutScreenState extends State<AboutScreen> {
  Map<String, dynamic>? _eval;
  bool _isLoading = true;

  @override
  void initState() {
    super.initState();
    _loadEval();
  }

  Future<void> _loadEval() async {
    try {
      final raw = await rootBundle.loadString('assets/config/eval_results.json');
      setState(() {
        _eval = json.decode(raw) as Map<String, dynamic>;
        _isLoading = false;
      });
    } catch (e) {
      debugPrint('[About] Failed to load eval_results.json: $e');
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    final ev = _eval;
    final theme = Theme.of(context);
    final cs = theme.colorScheme;

    // Pull numbers from eval_results.json
    final metrics = ev?['deployed_model_metrics'] as Map<String, dynamic>?;
    final perClass = (metrics?['per_class'] as List<dynamic>?) ?? [];
    final modelId = ev?['model_identity'] as Map<String, dynamic>?;
    final evalSet = ev?['evaluation_set'] as Map<String, dynamic>?;

    return Scaffold(
      appBar: AppBar(title: const Text('About')),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [

          // ── App identity ──────────────────────────────────────────────
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                        color: cs.primaryContainer, shape: BoxShape.circle),
                    child: Icon(Icons.eco_rounded,
                        size: 28, color: cs.onPrimaryContainer),
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('Lemon Leaf Classifier',
                            style: theme.textTheme.titleMedium
                                ?.copyWith(fontSize: 16)),
                        const SizedBox(height: 2),
                        Text('Version 1.0.0',
                            style: TextStyle(
                                fontSize: 13, color: cs.onSurfaceVariant)),
                        const SizedBox(height: 4),
                        Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 4),
                          decoration: BoxDecoration(
                            color: const Color(0xFFFFFBE6),
                            borderRadius: BorderRadius.circular(6),
                            border: Border.all(
                                color: Colors.amber.shade300
                                    .withValues(alpha: 0.7)),
                          ),
                          child: const Text(
                            'Research prototype — not a substitute for expert diagnosis.',
                            style: TextStyle(
                                fontSize: 11, color: Color(0xFF5A4000)),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),

          const SizedBox(height: 16),

          // ── Model identity ────────────────────────────────────────────
          _sectionHeader('Deployed Model'),
          const SizedBox(height: 8),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(14),
              child: Column(
                children: [
                  _metricRow('Architecture',
                      modelId?['architecture'] ?? 'convnext_tiny (timm)'),
                  _metricRow('Checkpoint',
                      modelId?['checkpoint'] ?? 'bb_convnext_tiny_320_f2_s42.pt'),
                  _metricRow('Fold index',
                      '${modelId?['fold_index'] ?? 2} (zero-based)'),
                  _metricRow('Seed', '${modelId?['seed'] ?? 42}'),
                  _metricRow('Format',
                      modelId?['deployed_format'] ?? 'FP32 ONNX (opset 17)'),
                  _metricRow('Input resolution', '320 × 320 px'),
                  _metricRow('Classes', '5'),
                  _metricRow('Runtime', 'ONNX Runtime Android (on-device)'),
                ],
              ),
            ),
          ),

          const SizedBox(height: 16),

          // ── Model performance ─────────────────────────────────────────
          _sectionHeader('Test-Set Performance'),
          const SizedBox(height: 4),
          Text(
            'Evaluated on ${evalSet?['n_test'] ?? 418} locked test images '
            '(split == test in split_assignment.csv; never used for '
            'threshold selection).',
            style: TextStyle(fontSize: 12, color: cs.onSurfaceVariant),
          ),
          const SizedBox(height: 8),

          if (metrics != null) ...[
            Card(
              child: Padding(
                padding: const EdgeInsets.all(14),
                child: Column(
                  children: [
                    _metricRow('Accuracy',
                        _pct(metrics['accuracy'])),
                    _metricRow('Balanced Accuracy',
                        _pct(metrics['balanced_accuracy'])),
                    _metricRow('Macro-F1',
                        _pct(metrics['macro_f1'])),
                    _metricRow('Log Loss',
                        (metrics['log_loss'] as num).toStringAsFixed(4)),
                    if (perClass.isNotEmpty) ...[
                      const Divider(height: 16),
                      const Align(
                        alignment: Alignment.centerLeft,
                        child: Text('Per-Class Recall  (Wilson 95 % CI)',
                            style: TextStyle(
                                fontWeight: FontWeight.bold, fontSize: 13)),
                      ),
                      const SizedBox(height: 6),
                      ...perClass.map((pc) {
                        final cls = pc['class'] as String;
                        final recall = (pc['recall'] as num).toDouble();
                        final lo = (pc['wilson_ci_95_lower'] as num).toDouble();
                        final hi = (pc['wilson_ci_95_upper'] as num).toDouble();
                        final n = pc['n_test'] as int;
                        return _recallRow(
                          kClassDisplayNames[cls] ?? cls,
                          recall, lo, hi, n,
                        );
                      }),
                    ],
                  ],
                ),
              ),
            ),

            // HLB small-sample note
            const SizedBox(height: 6),
            Text(
              'HLB recall (87.9 %) is based on only 33 test images; the '
              'Wilson 95 % CI is wide [72.7 %, 95.2 %].',
              style: const TextStyle(
                  fontSize: 11,
                  fontStyle: FontStyle.italic,
                  color: Colors.black54),
            ),
          ],

          const SizedBox(height: 16),

          // ── Abstention thresholds ─────────────────────────────────────
          _sectionHeader('Abstention (Low-Confidence Handling)'),
          const SizedBox(height: 8),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(14),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: const [
                  Text(
                    'If the model\'s top-1 probability < τ = 0.53  OR  '
                    '(top-1 − top-2) margin < δ = 0.24, the result is '
                    'shown as "Uncertain" rather than accepted.',
                    style: TextStyle(fontSize: 12, height: 1.4),
                  ),
                  SizedBox(height: 6),
                  Text(
                    'τ and δ were derived from 1,541 out-of-fold predictions '
                    'of all 5 convnext_tiny@320 folds — training data only, '
                    'never from the 418 test images.',
                    style: TextStyle(
                        fontSize: 11,
                        fontStyle: FontStyle.italic,
                        color: Colors.black54),
                  ),
                ],
              ),
            ),
          ),

          const SizedBox(height: 16),

          // ── Recognised conditions ─────────────────────────────────────
          _sectionHeader('Recognised Conditions'),
          const SizedBox(height: 8),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(14),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: kClassLabels
                    .map((l) => Padding(
                          padding: const EdgeInsets.symmetric(vertical: 4),
                          child: Row(
                            children: [
                              Icon(_iconForClass(l),
                                  size: 16, color: cs.primary),
                              const SizedBox(width: 8),
                              Expanded(
                                child: Text(kClassDisplayNames[l] ?? l,
                                    style:
                                        const TextStyle(fontSize: 13)),
                              ),
                            ],
                          ),
                        ))
                    .toList(),
              ),
            ),
          ),

          const SizedBox(height: 16),

          // ── Credits & licences ────────────────────────────────────────
          _sectionHeader('Credits & Licences'),
          const SizedBox(height: 8),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(14),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: const [
                  _CreditRow('Dataset',
                      'Lemon leaf image dataset, Mendeley Data, v4, '
                      'DOI: [DOI TO BE ADDED BY USER]'),
                  _CreditRow('Backbone',
                      'PyTorch Image Models (timm, Ross Wightman) — Apache 2.0'),
                  _CreditRow(
                      'Pretrained weights', 'ImageNet-1k (timm default)'),
                  _CreditRow(
                      'ONNX Runtime', 'Microsoft ONNX Runtime Mobile — MIT'),
                  _CreditRow(
                      'Framework', 'Flutter / Dart (Google) — BSD-3'),
                ],
              ),
            ),
          ),

          const SizedBox(height: 20),
        ],
      ),
    );
  }

  // ── Helpers ──────────────────────────────────────────────────────────────

  static String _pct(dynamic v) =>
      '${((v as num).toDouble() * 100).toStringAsFixed(2)} %';

  Widget _sectionHeader(String text) => Text(text,
      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15));

  Widget _metricRow(String label, String value) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(
          children: [
            Expanded(
                child: Text(label,
                    style: const TextStyle(fontSize: 13))),
            const SizedBox(width: 8),
            Text(value,
                style: const TextStyle(
                    fontWeight: FontWeight.bold, fontSize: 13)),
          ],
        ),
      );

  Widget _recallRow(
      String label, double recall, double lo, double hi, int n) =>
      Padding(
        padding: const EdgeInsets.symmetric(vertical: 3),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Expanded(
                    child: Text(label,
                        style: const TextStyle(fontSize: 12))),
                Text('${(recall * 100).toStringAsFixed(1)} %',
                    style: const TextStyle(
                        fontWeight: FontWeight.bold, fontSize: 12)),
              ],
            ),
            Text(
              'n = $n  •  Wilson 95 % CI: '
              '[${(lo * 100).toStringAsFixed(1)} %, ${(hi * 100).toStringAsFixed(1)} %]',
              style: const TextStyle(
                  fontSize: 10,
                  color: Colors.black45,
                  fontStyle: FontStyle.italic),
            ),
          ],
        ),
      );

  /// Returns the correct icon per disease class.
  /// - HLB: pathogen/virus icon
  /// - Leafminer, Swallowtail: pest/insect icon
  /// - Leaf Curl: leaf distortion icon
  /// - Healthy: eco leaf icon
  static IconData _iconForClass(String label) {
    switch (label) {
      case kHlbClassLabel:          return Icons.coronavirus_outlined;
      case 'citrus_leafminer':      return Icons.pest_control_outlined;
      case 'swallowtail_herbivory': return Icons.pest_control_rodent_outlined;
      case 'citrus_leaf_curl':      return Icons.change_history_outlined;
      case 'healthy_lemon_leaf':    return Icons.eco_rounded;
      default:                      return Icons.eco_outlined;
    }
  }
}

class _CreditRow extends StatelessWidget {
  final String label;
  final String value;
  const _CreditRow(this.label, this.value);

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label,
              style: const TextStyle(
                  fontWeight: FontWeight.bold, fontSize: 12)),
          Text(value,
              style: const TextStyle(fontSize: 12, height: 1.4)),
        ],
      ),
    );
  }
}
